static class RebirthNativeItemCodec {
 public static string Encode(ItemValue item){using(var s=new MemoryStream())using(var w=new BinaryWriter(s)){w.Write(item.type);w.Write(item.Seed);w.Write(item.Texture);w.Write(item.Metadata.Count);foreach(var p in item.Metadata){w.Write(p.Key);w.Write(p.Value);}return Convert.ToBase64String(s.ToArray());}}
 public static bool TryDecode(string image,out ItemValue item){item=null;try{using(var s=new MemoryStream(Convert.FromBase64String(image)))using(var r=new BinaryReader(s)){var v=new ItemValue{type=r.ReadInt32(),Seed=r.ReadUInt16(),Texture=r.ReadString()};int n=r.ReadInt32();if(n<0||n>100)return false;for(int i=0;i<n;i++)v.Metadata.Add(r.ReadString(),r.ReadString());if(s.Position!=s.Length)return false;item=v;return true;}}catch{return false;}}
}
