 private static PlayerDataFile FileFor(Dictionary<string,float> values,bool duplicate=false,bool trailing=false){var stream=new MemoryStream();using(var writer=new BinaryWriter(stream,Encoding.UTF8,true)){writer.Write((byte)EntityBuffs.Version);writer.Write((ushort)0);writer.Write((ushort)(values.Count+(duplicate?1:0)));foreach(var pair in values){writer.Write(pair.Key);writer.Write(pair.Value);}if(duplicate){writer.Write("rbFarmingWater_id0");writer.Write(0f);}if(trailing)writer.Write((byte)1);}stream.Position=0;return new PlayerDataFile{buffData=stream};}
