 public static void Main(){
  var operation=Guid.NewGuid();var original=ItemClass.GetItem("drinkJarEmpty");original.Texture="original texture";original.SetMetadata("unrelated","input identity");var reserved=Item(RebirthNativeItemCodec.Encode(original));reserved.SetMetadata(Marker,operation.ToString("N"));var output=ItemClass.GetItem("drinkJarRiverWater");output.SetMetadata(Marker,operation.ToString("N"));
