  var decoded=Decode(Encode(record));Check(SameOriginal(record,decoded),"canonical original roundtrip failed");Check(Exact(new ItemStack(original,3),record.Before,3),"exact original container refused");var changed=Item(record.Before);changed.Texture="different";Check(!Exact(new ItemStack(changed,3),record.Before,3),"changed input metadata/texture accepted");Check(!Exact(new ItemStack(original,2),record.Before,3),"changed original count accepted");
  var bad=Item(record.Output);bad.SetMetadata("unrelated","input identity");string intended=record.Output;record.Output=Native(bad);Check(Rejected(record),"source metadata carried into a fresh target conversion");record.Output=intended;
  record.Source=Guid.NewGuid();record.Revision=1;record.WaterBefore=10;record.WaterAfter=7;record.MaxWater=100;Decode(Encode(record));record.WaterAfter=6;Check(Rejected(record),"wrong whole-stack water count accepted");record.WaterAfter=7;record.State=1;Check(Rejected(record),"source intent became publication without native proof");record.Digest=new string('a',64);record.Generation=1;Decode(Encode(record));
  var declined=Decode(Encode(decoded));declined.State=3;Decode(Encode(declined));declined.Source=Guid.NewGuid();Check(Rejected(declined),"decline tombstone can conceal a source mutation");
  record.State=0;record.Digest="";record.Generation=0;var tank=new TileEntityWaterTankRebirth{WaterIncarnation=record.Source,WaterExchangeOperation=record.Previous,WaterExchangeRevision=record.Revision-1,waterCount=record.WaterBefore};Check(CanApplyPrepared(record,tank,record.Raw),"exact original tank before-effect refused");Check(CanCloseEndedNoEffect(record,tank,record.Raw,record.Deaths+1,true),"positive ended unchanged source refused");Check(!CanCloseEndedNoEffect(record,tank,record.Raw,record.Deaths+1,false),"death counter alone released source reservation");Check(!CanCloseEndedNoEffect(record,tank,record.Raw,record.Deaths,true),"same-life original marked ended");record.Invoking=true;Check(!CanCloseEndedNoEffect(record,tank,record.Raw,record.Deaths+1,true),"ambiguous invoking original released as no effect");Check(!CanApplyPrepared(record,tank,record.Raw),"interrupted effect replayed even with equal water preimage");tank.WaterExchangeOperation=record.Operation;tank.WaterExchangeRevision=record.Revision;tank.WaterExchangeBefore=record.WaterBefore;tank.WaterExchangeAfter=record.WaterAfter;tank.waterCount=record.WaterAfter+1;Check(MatchesStamp(record,tank),"later legitimate water update erased original stamp");tank.WaterIncarnation=Guid.NewGuid();Check(!MatchesStamp(record,tank),"replacement tank inherited original mutation proof");record.Invoking=false;
  var player=new EntityPlayerLocal();var attempt=new Attempt{Record=record,Player=player};player.inventory.ItemGrid.items[record.Slot]=new ItemStack(original,record.Count);Inventory.Refused=true;Check(!Set(attempt,record.Before,record.Reserved)&&Exact(player.inventory.GetItem(record.Slot),record.Before,record.Count),"refused native setter became owner publication");Inventory.Refused=false;Check(Set(attempt,record.Before,record.Reserved)&&player.inventory.Writes==1,"exact native original reservation refused");Check(!Consume(player.inventory.ItemGrid,record.Slot,player.inventory.Last),"disposed permit authorized later native write");Check(!Set(attempt,record.Before,record.Reserved)&&player.inventory.Writes==1,"source replacement replayed");Check(Set(attempt,record.Reserved,record.Output)&&player.inventory.Writes==2,"original fresh output setter refused");ScopeAllowed=false;Check(!Set(attempt,record.Output,record.Before)&&player.inventory.Writes==2,"stale actor mutated slot");ScopeAllowed=true;
  var reclaimedBag=new ItemStack[20];var reclaimedBelt=new ItemStack[20];reclaimedBag[7]=new ItemStack(Item(record.Reserved),record.Count);Check(TryLocateCustody(record,reclaimedBag,reclaimedBelt,null,out bool reclaimedInBag,out int reclaimedSlot)&&reclaimedInBag&&reclaimedSlot==7,"reclaimed original used obsolete source slot");reclaimedBelt[9]=new ItemStack(Item(record.Output),record.Count);Check(!TryLocateCustody(record,reclaimedBag,reclaimedBelt,null,out _,out _),"duplicate reserved/output custody accepted");reclaimedBelt[9]=null;Check(!TryLocateCustody(record,reclaimedBag,reclaimedBelt,new ItemStack(Item(record.Reserved),record.Count),out _,out _),"cursor duplicate accepted");reclaimedBag[7].count--;Check(!TryLocateCustody(record,reclaimedBag,reclaimedBelt,null,out _,out _),"split original was regranted whole output");reclaimedBag[7].count++;player.bag.ItemGrid.items=reclaimedBag;attempt.CustodyBag=true;attempt.CustodySlot=7;Check(!Set(attempt,record.Reserved,record.Output),"duplicate output event replaced immutable original publication");attempt.CustodyBag=false;attempt.CustodySlot=-1;SetPhase(player,record,1f);Check(player.Buffs.Values.Count==9,"water receipt grows per-operation native CVars");Check(Buff(FileFor(player.Buffs.Values),record,out float phase)&&phase==1f,"same-file exact GUID/phase rejected");Check(!Buff(FileFor(player.Buffs.Values,true),record,out _),"duplicate native GUID limb accepted");Check(!Buff(FileFor(player.Buffs.Values,false,true),record,out _),"trailing native buff bytes accepted");
  var other=Decode(Encode(record));other.Operation=Guid.NewGuid();Check(!Buff(FileFor(player.Buffs.Values),other,out _),"another original GUID supplied phase proof");player.Buffs.Values["rbFarmingWater_id0"]=.5f;Check(!Buff(FileFor(player.Buffs.Values),record,out _),"fractional GUID limb accepted");SetPhase(player,record,2f);Check(Buff(FileFor(player.Buffs.Values),record,out phase)&&phase==2f,"native output phase rejected");
  var fatal=new Fatal{Operation=record.Operation,Binding=Binding(record),World=record.World,Owner=record.Owner,Creation=record.Creation,Deaths=record.Deaths,Entity=7,Mode=0,FileProof=new string('a',64)};string fatalPath=FatalPath(record);Directory.CreateDirectory(Path.GetDirectoryName(fatalPath));try{File.WriteAllText(fatalPath,FatalImage(fatal));Check(ReadFatal(record,out var readFatal)&&readFatal.Binding==Binding(record),"exact original native fatal receipt refused");fatal.Binding=new string('b',64);File.WriteAllText(fatalPath,FatalImage(fatal));Check(!ReadFatal(record,out _),"other original fatal binding admitted");fatal.Binding=Binding(record);fatal.FileProof=new string('z',64);File.WriteAllText(fatalPath,FatalImage(fatal));Check(!ReadFatal(record,out _),"malformed native file proof admitted");}finally{Directory.Delete(GameIO.Root,true);}SetPhase(player,record,1f);Check(player.Buffs.Values.Count==9,"repeated original action leaked native receipt keys");
  Check(AdvancedFarmingItemWaterExchange.GetWaterDelta("bucketEmpty",1,200,400)==-200,"bucket draw amount changed");Check(AdvancedFarmingItemWaterExchange.GetWaterDelta("bucketRiverWater",2,0,400)==0,"stacked bucket input accepted");Check(AdvancedFarmingItemWaterExchange.GetWaterDelta("drinkJarEmpty",3,2,400)==0,"insufficient water admitted");Check(AdvancedFarmingItemWaterExchange.GetWaterDelta("drinkJarBoiledWater",3,398,400)==0,"overcapacity filled jars admitted");
  Console.WriteLine("PASS actual water canonical original/conversion/count/GUID fixed-marker methods; native codec/file readers are explicit doubles; NOT multiplayer certification");
